import math

def bisect(f, lo, hi, tol):
    flo, fhi = f(lo), f(hi)
    calls = 2
    if flo == 0:
        return lo, calls
    if fhi == 0:
        return hi, calls
    if (flo > 0) == (fhi > 0):
        raise ValueError('no sign change')
    while hi - lo >= tol:
        mid = (lo + hi) / 2
        if mid == lo or mid == hi:
            break
        fm = f(mid)
        calls += 1
        if (fm > 0) == (flo > 0):
            lo, flo = mid, fm
        else:
            hi = mid
    return (lo + hi) / 2, calls

def secant(f, x0, x1, tol):
    f0, f1 = f(x0), f(x1)
    calls = 2
    while abs(x1 - x0) >= tol and f1 != f0:
        x0, x1 = x1, x1 - f1 * (x1 - x0) / (f1 - f0)
        f0, f1 = f1, f(x1)
        calls += 1
    return x1, calls

def newton(f, df, x0, tol, maxit=50):
    x, calls = x0, 0
    for _ in range(maxit):
        fx = f(x)
        calls += 1
        step = fx / df(x)
        x -= step
        if abs(step) < tol:
            return x, calls
    raise RuntimeError('no convergence')

def observed_order(errs):
    e0, e1, e2 = errs[-3], errs[-2], errs[-1]
    return math.log(e2 / e1) / math.log(e1 / e0)

